"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7091],{1595(e){e.exports=JSON.parse('{"title":"React Query, \uc815\ub9d0 \ub9cc\ub2a5\uc778\uac00?","date":"2025-01-10","coverUrl":"/kudzu-based-bench/assets/notion/3c9f9c2dde51753e.png","html":"<h2 data-notion-block-id=\\"172e548d-8a8e-80af-8dbd-ee8123aab264\\" id=\\"172e548d-8a8e-80af-8dbd-ee8123aab264\\">React Query, \uc815\ub9d0 \ub9cc\ub2a5\uc778\uac00?</h2><a href=\\"https://gitnation.com/contents/react-query-the-bad-parts\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/react-query-the-bad-parts</a><p data-notion-block-id=\\"173e548d-8a8e-80bb-92db-d2824afc3184\\">React Query(\ud604\uc7ac\ub294 Tanstack Query)\ub97c \ub2e4\ub8ec \ub9ce\uc740 \uae00 \uc911\uc5d0, Tanstack Query\uc758 \uc7a5\uc810\uacfc \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0\uc5d0 \ucd08\uc810\uc774 \ub9de\ucdb0\uc838\uc788\uc2b5\ub2c8\ub2e4. \uc774 \ubc1c\ud45c\uc5d0\uc11c\ub294 Tanstack Query \ub2e8\uc810\ub4e4\uc744 \ub098\uc5f4\ud558\uba70, \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\uac8c \uc0ac\uc6a9\ud558\ub294 \ubc95\uc744 \uc775\ud614\uc73c\uba74 \ud569\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-80c6-8224-f9618dd9926f\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uae30</a>\uae00\uc774\ub098, Redux \uac1c\ubc1c\uc790\uc758 <a href=\\"https://blog.isquaredsoftware.com/2021/01/context-redux-differences/\\">React Context\uac00 \uc0c1\ud0dc\uad00\ub9ac \ub3c4\uad6c\uac00 \uc544\ub2cc \uc774\uc720</a>\ub3c4 \ube44\uc2b7\ud55c \uacb0\uc744 \ub744\ubbc0\ub85c, \uc774\uac83 \ub610\ud55c \uc77d\uc5b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. <a href=\\"https://tkdodo.eu/blog/react-query-the-bad-parts\\">\uae00 \ubc84\uc804</a>\ub3c4 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"173e548d-8a8e-8037-9c7c-df652c6e8b82\\" id=\\"173e548d-8a8e-8037-9c7c-df652c6e8b82\\">Dropdown\uc758 \uc228\uaca8\uc9c4 \uc694\uad6c\uc0ac\ud56d\ub4e4</h2><a href=\\"https://reshaped.so/blog/building-a-dropdown\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reshaped.so/blog/building-a-dropdown</a><p data-notion-block-id=\\"173e548d-8a8e-8014-bcfc-c3717c28dfa6\\">\uc218\ub9ce\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \uad6c\ud604\ub418\uc5b4 \uc788\ub294 Dropdown\uc5d0\uc11c \uace0\ub824\ud558\ub294 \uc694\uad6c\uc0ac\ud56d\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uad6c\ud604 \ub300\uc2e0 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uac00\uc838\ub2e4 \uc4f0\ub294 \uac83\uc774 \uc88b\uc740 \uc774\uc720\ub098, \ubcf4\ud1b5 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ubb38\uc11c\uc5d0\uc11c \ubb34\uc2dc\ub418\ub294 \uae30\ub2a5\ub4e4\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"173e548d-8a8e-80e7-ae83-f572dd0b3c3b\\" id=\\"173e548d-8a8e-80e7-ae83-f572dd0b3c3b\\">Next.js, \uaf2d \ud544\uc694\ud55c\uac00\uc694?</h2><a href=\\"https://www.comfydeploy.com/blog/you-dont-need-nextjs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.comfydeploy.com/blog/you-dont-need-nextjs</a><p data-notion-block-id=\\"173e548d-8a8e-8089-be6c-ffe7105e2589\\">\ubb3c\ub860 \ud2b9\uc774\ud55c \uc694\uad6c\uc0ac\ud56d\uc774\ub77c\uace0 \uc0dd\uac01\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c Next.js\uac00 \ud544\uc694 \uc5c6\uc744 \uc218\ub3c4, \ud639\uc740 SSR \ub610\ud55c \ud544\uc694\uc5c6\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. Next.js\uc758 \ub2e8\uc810\uc5d0 \uce58\uc6b0\uccd0\uc9c4 \uae00\uc774\uc9c0\ub9cc, \uac10\uc548\ud558\uace0 \ubcfc\ub9cc \ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"173e548d-8a8e-8041-bde9-f197c379ff99\\" id=\\"173e548d-8a8e-8041-bde9-f197c379ff99\\">Remix\uc5d0\uc11c \ubcf4\uc548 \ud655\uc778\ud558\uae30</h2><a href=\\"https://blog.arcjet.com/remix-security-checklist/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.arcjet.com/remix-security-checklist/</a><p data-notion-block-id=\\"173e548d-8a8e-801c-8eb1-fd9c8d294c5b\\">Remix\uc5d0\uc11c \ud655\uc778\ud574\uc57c \ud560 \ubcf4\uc548\uc744 \uc124\uba85\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, \ub514\ud39c\ub358\uc2dc, \ud658\uacbd\ubcc0\uc218 \ud655\uc778\u2026 \uc5ec\ub7ec\uac00\uc9c0 \uc694\uc18c\ub294 \ub2e4\ub978 \ud504\ub860\ud2b8\uc5d4\ub4dc \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\ub3c4 \ud544\uc694\ud55c \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub4e4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"173e548d-8a8e-8036-983a-fdae70e2feef\\" id=\\"173e548d-8a8e-8036-983a-fdae70e2feef\\">\uae34 \uc2e4\ud589\uc2dc\uac04 \ucabc\uac1c\uae30</h2><a href=\\"https://calendar.perfplanet.com/2024/breaking-up-with-long-tasks-or-how-i-learned-to-group-loops-and-wield-the-yield/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://calendar.perfplanet.com/2024/breaking-up-with-long-tasks-or-how-i-learned-to-group-loops-and-wield-the-yield/</a><p data-notion-block-id=\\"173e548d-8a8e-80e4-8a4d-e6cf0f5bd24d\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/156e548d-8a8e-8024-aec1-fd27c897c295#156e548d-8a8e-80df-95e3-c34f92e4fc7f\\">React\uc5d0\uc11c INP\uac1c\uc120\ud558\uae30</a>\ubcf4\ub2e4 \uac04\ub2e8\ud558\uac8c, \uadf8\ub9ac\uace0 \uc77c\ubd80\ub9cc \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, Long Task\uc758 \uac1c\ub150\uc744 \uc54c\uc544\ubcf4\ub294\ub370\uc5d0\ub294 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"173e548d-8a8e-80cf-85fd-fac67de4e900\\" id=\\"173e548d-8a8e-80cf-85fd-fac67de4e900\\">Static Hermes\uc758 \ud604\uc7ac</h2><a href=\\"https://x.com/tmikov/status/1869945330638442651\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://x.com/tmikov/status/1869945330638442651</a><p data-notion-block-id=\\"173e548d-8a8e-8042-ba92-fe1b85d0314e\\">Static Hermes\ub294 \uc791\ub144\ubd80\ud130 \uc18c\uac1c\ub41c JS\ub97c \ube60\ub974\uac8c \ud558\uae30 \uc704\ud574 \ucef4\ud30c\uc77c JS\ub85c \ubc14\uafd4\uc8fc\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/bafbcbbf-9100-45c9-b683-a1a5134930fa#30fd9bf2-36bd-4f5d-afd4-7a8cad87d0ad\\">Static Hermes, RN\uc744 \ub354 \ube60\ub974\uac8c \ud574\uc90d\ub2c8\ub2e4</a>). \uc544\uc9c1 \uc548\uc815\ub418\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \uac78\ub9ac\uaca0\uc9c0\ub9cc, ES6 \uc9c0\uc6d0 \uc644\ub8cc \ub4f1 \uae30\ub2a5 \uaca9\ucc28\ub97c \ud574\uc18c\ud558\uace0, \uc131\ub2a5 \ud5a5\uc0c1\ub610\ud55c \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\uc73c\ub2c8, \uc9c0\ucf1c\ubd10\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"173e548d-8a8e-8001-8648-c0d508826606\\" id=\\"173e548d-8a8e-8001-8648-c0d508826606\\">KMP \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://www.callstack.com/blog/from-native-to-multiplatform-development-unpacking-kotlin-and-compose\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/from-native-to-multiplatform-development-unpacking-kotlin-and-compose</a><p data-notion-block-id=\\"173e548d-8a8e-803e-8ee9-efa984dc9fce\\">React Native \uac1c\ubc1c\uc790\uac00 \ubc14\ub77c\ubcf8 KMP\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. KMP\uc758 \ubaa8\ub4e0 \uac83\uc744 \uc54c \uc218\ub294 \uc5c6\uaca0\uc9c0\ub9cc, \uc7a5\ub2e8\uc810\uc744 \ube44\uad50\ud574\ubcf4\uae30\uc5d4 \uc88b\uc2b5\ub2c8\ub2e4.</p>"}')}}]);